Certainly! Below is a simple C++ program that calculates the **nth Fibonacci number** using **recursion**:

```cpp
#include <iostream>
using namespace std;

// Function to compute the nth Fibonacci number using recursion
int fibonacci(int n) {
    if (n <= 0) {
        return 0;
    } else if (n == 1) {
        return 1;
    } else {
        return fibonacci(n - 1) + fibonacci(n - 2);
    }
}

int main() {
    int n;

    // Input from the user
    cout << "Enter the position (n) to find the Fibonacci number: ";
    cin >> n;

    // Check for non-negative input
    if (n < 0) {
        cout << "Please enter a non-negative integer." << endl;
    } else {
        int result = fibonacci(n);
        cout << "The " << n << "th Fibonacci number is: " << result << endl;
    }

    return 0;
}
```

